"""
知识树构建系统 - Prompt 工厂模块

包含所有阶段的中文 Prompt 模板：
- Preprocess 阶段: 基础树生成、检查、改进
- Rich 阶段: 查询生成、搜索清洗、报告生成
- Postprocess 阶段: 标签关系、别名描述
"""

from typing import Dict, Any, List


class PromptFactory:
    """Prompt 模板工厂类"""

    # ============ Preprocess 阶段 ============

    @staticmethod
    def base_tree_prompt(field: str, root_node_name: str, numbered_text: str) -> str:
        """基础树生成 Prompt"""
        return f"""你是一位专业的知识结构分析专家。请将以下{field}领域的文本转换为分层的思维导图结构。

**根节点名称**: {root_node_name}

**带编号的文本内容**:
{numbered_text}

**任务要求**:
1. 分析文本的逻辑结构，提取核心概念和层级关系
2. 构建一个完整的树形结构，根节点为"{root_node_name}"
3. 每个节点需要记录它所依据的文本块编号（reference_id_list）
4. 树的深度应该合理（建议2-4层），节点数量适中
5. 节点标题应简洁明确，准确反映内容要点

**输出格式** (严格的JSON格式):
{{
    "title": "{root_node_name}",
    "reference_id_list": ["001", "002", "..."],
    "children": [
        {{
            "title": "一级节点1",
            "reference_id_list": ["003", "004"],
            "children": [
                {{
                    "title": "二级节点1-1",
                    "reference_id_list": ["005"],
                    "children": []
                }}
            ]
        }}
    ]
}}

**注意事项**:
- 必须输出纯JSON格式，不要包含任何其他文本
- reference_id_list 必须是字符串列表，格式如 ["001", "002"]
- 确保所有引用的编号都在文本中存在
- 叶节点的 children 应为空列表 []

请开始分析并生成树形结构："""

    @staticmethod
    def check_base_tree_prompt(base_tree: Dict[str, Any], field: str, root_node_name: str) -> str:
        """基础树检查 Prompt"""
        import json
        tree_str = json.dumps(base_tree, ensure_ascii=False, indent=2)

        return f"""你是一位严格的知识结构审查专家。请检查以下{field}领域的树形结构的质量。

**根节点名称**: {root_node_name}

**待检查的树结构**:
```json
{tree_str}
```

**检查维度**:
1. **结构完整性** (30分): 是否有根节点，层次是否清晰，是否有孤立节点
2. **内容准确性** (30分): 节点标题是否准确，reference_id_list是否合理
3. **逻辑性** (20分): 父子关系是否合理，分类是否科学
4. **覆盖度** (20分): 是否覆盖了主要内容，是否有遗漏

**评分标准**:
- 90-100分: 优秀，结构完美，可以直接使用
- 70-89分: 良好，结构合理，有小问题但可接受
- 60-69分: 及格，结构基本合理，但需要改进
- 0-59分: 不及格，结构有明显问题，必须重构

**输出格式** (严格的JSON格式):
{{
    "status": "PASS 或 FAIL",
    "score": 85,
    "check": "一句总评或具体建议（如果PASS则写'PASS'）"
}}

请给出你的评估："""

    @staticmethod
    def improve_base_tree_with_feedback_prompt(
        base_tree: Dict[str, Any], 
        field: str, 
        root_node_name: str, 
        feedback: Dict[str, Any]
    ) -> str:
        """基础树改进 Prompt"""
        import json
        tree_str = json.dumps(base_tree, ensure_ascii=False, indent=2)
        feedback_str = json.dumps(feedback, ensure_ascii=False, indent=2)

        return f"""你是一位知识结构优化专家。请根据反馈意见改进以下{field}领域的树形结构。

**根节点名称**: {root_node_name}

**当前树结构**:
```json
{tree_str}
```

**反馈意见**:
```json
{feedback_str}
```

**改进要求**:
1. 针对反馈中指出的问题进行修正
2. 保持JSON格式的完整性和正确性
3. 保持根节点名称不变
4. 优化节点标题和层级关系
5. 确保 reference_id_list 的准确性

**输出格式** (严格的JSON格式，与原始格式相同):
{{
    "title": "{root_node_name}",
    "reference_id_list": ["..."],
    "children": [...]
}}

请输出改进后的树结构："""

    # ============ Rich 阶段 ============

    @staticmethod
    def search_query_generation_prompt(
        field: str, 
        path: str, 
        leaf_node: Dict[str, Any], 
        reference: str
    ) -> str:
        """搜索查询生成 Prompt"""
        return f"""你是一位专业的搜索查询专家。请判断是否需要对该叶节点进行网络搜索，并生成搜索查询。

**领域**: {field}
**节点路径**: {path}
**叶节点标题**: {leaf_node.get('title', '')}
**节点引用内容**:
{reference[:500]}...

**判断标准**:
1. 如果节点标题已经很具体（如"SVM基本原理"、"光催化剂制成工艺"），则不需要搜索
2. 如果节点标题过于笼统（如"基本原理"、"发展历程"），需要结合路径和领域进行搜索

**改造示例**:
- "基本原理" + 路径"神经网络" → 需要搜索 → "神经网络基本原理"
- "SVM基本原理" → 不需要搜索 → ""
- "发展历程" + 路径"人工智能" → 需要搜索 → "人工智能发展历程"

**输出格式** (严格的JSON格式):
{{
    "channel": "search 或 nosearch",
    "search_query": "搜索查询字符串（如果不需要搜索则为空字符串）"
}}

请分析并生成："""

    @staticmethod
    def check_query_prompt(search_query: str, field: str, path: str) -> str:
        """搜索查询检查 Prompt"""
        return f"""你是搜索查询质量审查专家。请检查以下搜索查询的质量。

**领域**: {field}
**节点路径**: {path}
**搜索查询**: {search_query}

**检查维度**:
1. 查询是否具有区分度（能否准确定位目标内容）
2. 查询是否包含必要的上下文信息
3. 查询长度是否合适（不要过长或过短）
4. 查询是否符合搜索引擎习惯

**输出格式** (严格的JSON格式):
{{
    "status": "PASS 或 FAIL",
    "score": 85,
    "check": "一句总评或具体建议"
}}

请给出评估："""

    @staticmethod
    def improve_query_with_feedback_prompt(
        search_query: str, 
        feedback: Dict[str, Any], 
        field: str, 
        path: str
    ) -> str:
        """搜索查询改进 Prompt"""
        import json
        feedback_str = json.dumps(feedback, ensure_ascii=False, indent=2)

        return f"""你是搜索查询优化专家。请根据反馈改进搜索查询。

**领域**: {field}
**节点路径**: {path}
**当前查询**: {search_query}

**反馈意见**:
```json
{feedback_str}
```

**输出格式** (严格的JSON格式):
{{
    "search_query": "改进后的搜索查询"
}}

请输出改进后的查询："""

    @staticmethod
    def clean_search_result_prompt(
        field: str, 
        path: str, 
        search_result: Dict[str, str], 
        leaf_node: Dict[str, Any]
    ) -> str:
        """搜索结果清洗 Prompt"""
        return f"""你是信息提取专家。请从搜索结果中提取与目标主题相关的内容。

**领域**: {field}
**节点路径**: {path}
**目标节点**: {leaf_node.get('title', '')}

**搜索结果**:
标题: {search_result.get('title', '')}
URL: {search_result.get('url', '')}
内容:
{search_result.get('content', '')[:1000]}...

**任务要求**:
1. 提取与目标节点直接相关的内容
2. 去除广告、导航、无关信息
3. 保持内容的完整性和逻辑性
4. 如果完全不相关，返回空字符串

**输出格式** (严格的JSON格式):
{{
    "relevant_content": "提取的相关内容（如果无相关内容则为空字符串）"
}}

请提取相关内容："""

    @staticmethod
    def research_result_to_report_prompt(
        field: str, 
        path: str, 
        reference: str, 
        leaf_node: Dict[str, Any], 
        relevant_contents: str
    ) -> str:
        """研究结果转报告 Prompt"""
        channel = "有网络搜索资料" if relevant_contents.strip() else "无网络搜索资料"

        return f"""你是专业的技术报告撰写专家。请基于原始文本和搜索资料撰写深度技术报告。

**领域**: {field}
**节点路径**: {path}
**报告主题**: {leaf_node.get('title', '')}
**资料来源**: {channel}

**原始文本内容**:
{reference[:1000]}...

**网络搜索资料**:
{relevant_contents[:2000] if relevant_contents.strip() else '（无网络搜索资料）'}...

**报告要求**:
1. 使用 Markdown 格式，包含标题、子标题、列表等
2. 内容深度：至少800字，详细阐述该主题
3. 结构清晰：引言→核心内容→总结
4. 准确性：基于给定资料，不可凭空捏造
5. 专业性：使用领域术语，保持技术深度

**输出格式** (Markdown纯文本，不要JSON包裹):
# {leaf_node.get('title', '')}

## 概述
...

## 详细内容
...

## 总结
...

请撰写专业报告："""

    @staticmethod
    def check_report_prompt(report: str, field: str, leaf_node: Dict[str, Any]) -> str:
        """报告检查 Prompt"""
        return f"""你是技术报告审查专家。请检查以下报告的质量。

**领域**: {field}
**报告主题**: {leaf_node.get('title', '')}

**报告内容**:
{report[:1500]}...

**检查维度**:
1. **完整性** (25分): 结构是否完整，是否有引言、正文、总结
2. **深度** (25分): 内容是否深入，是否达到800字以上
3. **准确性** (25分): 内容是否准确，是否有事实错误
4. **专业性** (25分): 语言是否专业，术语使用是否恰当

**输出格式** (严格的JSON格式):
{{
    "status": "PASS 或 FAIL",
    "score": 85,
    "check": "一句总评或具体建议"
}}

请给出评估："""

    @staticmethod
    def improve_report_with_feedback_prompt(
        report: str, 
        feedback: Dict[str, Any], 
        field: str, 
        leaf_node: Dict[str, Any]
    ) -> str:
        """报告改进 Prompt"""
        import json
        feedback_str = json.dumps(feedback, ensure_ascii=False, indent=2)

        return f"""你是技术报告优化专家。请根据反馈改进报告。

**领域**: {field}
**报告主题**: {leaf_node.get('title', '')}

**当前报告**:
{report[:1000]}...

**反馈意见**:
```json
{feedback_str}
```

**改进要求**:
1. 针对反馈中的问题进行修正
2. 保持 Markdown 格式
3. 确保专业性和准确性
4. 优化结构和深度

**输出格式** (Markdown纯文本，不要JSON包裹):
请输出改进后的完整报告："""

    # ============ Postprocess 阶段 ============

    @staticmethod
    def relation_labels_design_prompt(simplified_tree: Dict[str, Any], field: str) -> str:
        """关系和标签设计 Prompt"""
        import json
        tree_str = json.dumps(simplified_tree, ensure_ascii=False, indent=2)

        return f"""你是知识图谱设计专家。请为以下{field}领域的知识树设计标签和关系。

**简化树结构**:
```json
{tree_str}
```

**任务分四步完成**:

**Step 1: 设计全局标签和关系**
- 标签总数: ≤100个，每个标签长度2-5字
- 关系总数: ≤25个，每个关系长度2-5字
- 标签示例: "算法", "理论", "应用", "工具", "框架"
- 关系示例: "包含", "属于", "依赖", "实现", "扩展"

**Step 2: 为每个节点分配标签和关系**
- 每个节点: ≥2个标签（主标签+副标签）
- 主标签: 节点所属类别
- 副标签: 节点的具体属性
- 节点关系: 与父节点的逻辑关系（根节点关系为空字符串""）

**Step 3: 清洗包含关系**
- 如果标签"A"被标签"ABC"包含，删除"A"
- 如果关系"B"被关系"BCD"包含，删除"B"
- 保留最具体的标签和关系

**Step 4: 输出最终结构**

**输出格式** (严格的JSON格式):
{{
    "labels": ["标签1", "标签2", "..."],
    "relations": ["关系1", "关系2", "..."],
    "tree": {{
        "title": "根节点",
        "labels": ["主标签", "副标签1", "副标签2"],
        "relation": "",
        "children": [
            {{
                "title": "子节点",
                "labels": ["主标签", "副标签1"],
                "relation": "包含",
                "children": []
            }}
        ]
    }}
}}

请完成设计："""

    @staticmethod
    def relation_labels_check_prompt(
        beautified_tree: Dict[str, Any], 
        labels: List[str], 
        relations: List[str]
    ) -> str:
        """关系和标签检查 Prompt"""
        import json
        tree_str = json.dumps(beautified_tree, ensure_ascii=False, indent=2)

        return f"""你是知识图谱质量审查专家。请检查标签和关系的设计质量。

**美化树结构**:
```json
{tree_str}
```

**全局标签列表**: {labels}
**全局关系列表**: {relations}

**检查维度**:
1. **标签质量** (30分): 是否准确、是否有冗余、是否覆盖全面
2. **关系质量** (30分): 是否合理、是否有歧义、是否逻辑一致
3. **分配合理性** (20分): 每个节点的标签和关系是否恰当
4. **清洗完整性** (20分): 是否消除了包含关系

**输出格式** (严格的JSON格式):
{{
    "status": "PASS 或 FAIL",
    "score": 85,
    "check": "一句总评或具体建议",
    "issues": ["问题1", "问题2", "..."]
}}

请给出评估："""

    @staticmethod
    def relation_labels_improve_prompt(
        beautified_tree: Dict[str, Any], 
        labels: List[str], 
        relations: List[str], 
        feedback: Dict[str, Any]
    ) -> str:
        """关系和标签改进 Prompt"""
        import json
        tree_str = json.dumps(beautified_tree, ensure_ascii=False, indent=2)
        feedback_str = json.dumps(feedback, ensure_ascii=False, indent=2)

        return f"""你是知识图谱优化专家。请根据反馈改进标签和关系。

**当前美化树**:
```json
{tree_str}
```

**当前标签**: {labels}
**当前关系**: {relations}

**反馈意见**:
```json
{feedback_str}
```

**改进要求**:
1. 针对反馈问题进行修正
2. 保持JSON格式完整性
3. 确保标签和关系的一致性
4. 重新清洗包含关系

**输出格式** (与原始格式相同的JSON):
{{
    "labels": ["..."],
    "relations": ["..."],
    "tree": {{...}}
}}

请输出改进后的结构："""

    @staticmethod
    def alias_description_design_prompt(
        sub_tree: Dict[str, Any], 
        field: str
    ) -> str:
        """别名和描述设计 Prompt"""
        import json
        parent = sub_tree.get('parent', {})
        children = sub_tree.get('children', [])

        parent_str = json.dumps(parent, ensure_ascii=False, indent=2)
        children_str = json.dumps(children, ensure_ascii=False, indent=2)

        return f"""你是知识图谱语义增强专家。请为节点设计别名和描述。

**领域**: {field}

**父节点信息**:
```json
{parent_str}
```

**子节点信息**:
```json
{children_str}
```

**任务要求**:

1. **节点别名** (1-2个):
   - 同义词、简称、英文名等
   - 示例: "机器学习" → ["ML", "Machine Learning"]

2. **节点描述** (≥200字):
   - 基于reference内容进行精确定义
   - 说明节点的含义、作用、特点
   - 不可凭空捏造，必须有依据
   - 结合path和labels提供上下文

**输出格式** (严格的JSON格式):
{{
    "node_id": "{parent.get('node_id', '')}",
    "alias": ["别名1", "别名2"],
    "description": "详细描述（至少200字）..."
}}

请完成设计："""
